def listcameras(max = 10):
    available = []

    for index in range(max):
        cap = cv2.VideoCapture(index, cv2.CAP_DSHOW) if hasattr(cv2, 'CAP_DSHOW') else cv2.VideoCapture(index)

        if cap.isOpened():
            available.append(index)
            cap.release()
    return available


